665: function addCityBlock(scene, world, cx, cz) {
666:   const district = getDistrict(cx, cz)
667:   const isDowntown = district === 'downtown'
668:   const isWest = district === 'beach'
669:   const isIndustrial = district === 'docks'
670:   const lots = isDowntown ? [[-10, -10, 21, 20], [12, -10, 18, 20], [-11, 12, 20, 18], [12, 12, 18, 18]] : [[-9, -10, 19, 17], [11, -10, 17, 17], [-9, 11, 18, 16], [11, 11, 16, 16]]
671:   for (const [ox, oz, w, d] of lots) {
672:     if (Math.random() < (isWest ? 0.26 : 0.1)) continue
673:     let h
674:     if (isDowntown) h = 28 + Math.random() * 54
675:     else if (isIndustrial) h = 7 + Math.random() * 8
676:     else if (isWest) h = 6 + Math.random() * 12
677:     else h = 9 + Math.random() * 22
678:     if (Math.random() < 0.06) h = 2.5
679:     const style = isDowntown ? (Math.random() > 0.25 ? 'glass' : 'teal') : BUILDING_STYLES[Math.floor(Math.random() * BUILDING_STYLES.length)]
680:     const shop = !isDowntown && h < 25 && Math.random() > 0.35 ? SHOP_NAMES[Math.floor(Math.random() * SHOP_NAMES.length)] : null
681:     const neon = NEON[Math.floor(Math.random() * NEON.length)]
682:     makeBuilding(scene, world, cx + ox, cz + oz, w, d, h, style, Math.floor(Math.random() * 6), { shop, neon, signSide: Math.random() > 0.5 ? 1 : -1 })
683:   }
684: 
685:   if (isWest && Math.random() > 0.25) {
686:     for (let i = 0; i < 2; i++) addPalmAt(scene, world, cx - 16 + i * 9, cz + (i ? 17 : -18), 6.8 + Math.random() * 3, 0.16)
687:   }
688:   if (district === 'commercial' && Math.random() > 0.5) {
689:     addPalmAt(scene, world, cx - 19, cz + 18, 7.5, 0.2)
690:   }
691:   if (Math.random() > 0.72) addLampAt(scene, world, cx - 22, cz + 22, Math.random() > 0.5 ? 0 : Math.PI)
692:   if (Math.random() > 0.82) addLampAt(scene, world, cx + 22, cz - 22, Math.random() > 0.5 ? Math.PI : 0)
693:   if (isDowntown && Math.random() > 0.55) {
694:     addParkedCar(world, cx + 18, cz - 26, 0, [0x22262b, 0xd3d5d8, 0x8c1f28, 0x224f7a][Math.floor(Math.random() * 4)], 'sport')
695:   }
696: }
