698: function getDistrict(cx, cz) {
699:   if (cx <= -96) return 'beach'
700:   if (cx >= 96 && cz >= 96) return 'docks'
701:   if (cx >= 32 && cz <= -32) return 'downtown'
702:   if (cz >= 96) return 'suburbs'
703:   return 'commercial'
704: }
