706: function makeBuilding(scene, world, x, z, w, d, h, style, tint, options = {}) {
707:   const group = new THREE.Group()
708:   const baseColor = BUILDING_TINTS[tint % BUILDING_TINTS.length]
709:   const mat = new THREE.MeshStandardMaterial({ map: cloneFacade(style, w, h * 0.72), color: baseColor, roughness: style === 'glass' ? 0.42 : 0.7, metalness: style === 'glass' ? 0.32 : 0.04 })
710:   const lowerH = h > 52 ? h * 0.72 : h
711:   const body = new THREE.Mesh(new THREE.BoxGeometry(w, lowerH, d), mat)
712:   body.position.y = lowerH / 2 + 0.06
713:   body.castShadow = true
714:   body.receiveShadow = true
715:   body.userData.mergeBuilding = style
716:   group.add(body)
717: 
718:   let topW = w
719:   let topD = d
720:   if (h > 52) {
721:     const upperH = h - lowerH
722:     topW = w * 0.7
723:     topD = d * 0.72
724:     const upperMat = new THREE.MeshStandardMaterial({ map: cloneFacade(style, topW, upperH), color: baseColor, roughness: style === 'glass' ? 0.36 : 0.7, metalness: style === 'glass' ? 0.38 : 0.04 })
725:     const upper = new THREE.Mesh(new THREE.BoxGeometry(topW, upperH, topD), upperMat)
726:     upper.position.y = lowerH + upperH / 2 + 0.06
727:     upper.castShadow = true
728:     upper.receiveShadow = true
729:     upper.userData.mergeBuilding = style
730:     group.add(upper)
731:   }
732: 
733:   const capMat = new THREE.MeshStandardMaterial({ color: style === 'glass' ? 0x536166 : 0x8b7765, roughness: 0.78 })
734:   const cap = new THREE.Mesh(new THREE.BoxGeometry(topW + 0.35, 0.55, topD + 0.35), capMat)
735:   cap.position.y = h + 0.2
736:   group.add(cap)
737: 
738:   if (options.landmark || (style === 'glass' && h > 68)) {
739:     const neonMat = new THREE.MeshBasicMaterial({ color: options.landmark || (h > 90 ? 0x55ffe0 : 0xff5a86), transparent: true, opacity: 0.85, toneMapped: false })
740:     for (const y of [h - 1.4, h - 4.2]) {
741:       const band = new THREE.Mesh(new THREE.BoxGeometry(topW + 0.5, 0.22, topD + 0.5), neonMat)
742:       band.position.y = y
743:       group.add(band)
744:     }
745:     const crown = new THREE.Mesh(new THREE.BoxGeometry(0.25, 3.5, 0.25), new THREE.MeshStandardMaterial({ color: 0xc9d4d7, metalness: 0.9, roughness: 0.25 }))
746:     crown.position.y = h + 2.2
747:     group.add(crown)
748:   }
749: 
750:   if (!options.noRooftop && h > 12) {
751:     const acMat = new THREE.MeshStandardMaterial({ color: 0x7b8b8d, roughness: 0.65, metalness: 0.4 })
752:     for (let i = 0; i < 1; i++) {
753:       const ac = new THREE.Mesh(new THREE.BoxGeometry(1.3, 0.75, 1.1), acMat)
754:       ac.position.set((Math.random() - 0.5) * topW * 0.5, h + 0.85, (Math.random() - 0.5) * topD * 0.5)
755:       group.add(ac)
756:     }
757:     if (h > 34 && Math.random() > 0.5) {
758:       const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.1, 4 + Math.random() * 5, 5), new THREE.MeshStandardMaterial({ color: 0x777c80, metalness: 0.8, roughness: 0.35 }))
759:       antenna.position.set(0, h + 2.8, 0)
760:       group.add(antenna)
761:       const tip = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 6), new THREE.MeshStandardMaterial({ color: 0xff3c2f, emissive: 0xff1400, emissiveIntensity: 3 }))
762:       tip.position.y = h + 5.3
