768:     const front = new THREE.Mesh(new THREE.PlaneGeometry(Math.min(w * 0.65, 7), 1.4), new THREE.MeshBasicMaterial({ map: shopTexture(options.shop, options.neon || '#ff6b4a'), toneMapped: false }))
769:     front.position.set(0, 2.1, d / 2 + 0.07)
770:     group.add(front)
771:     const awning = new THREE.Mesh(new THREE.BoxGeometry(Math.min(w * 0.75, 8), 0.12, 1.4), new THREE.MeshStandardMaterial({ color: options.neon || 0xff6b4a, roughness: 0.75 }))
772:     awning.position.set(0, 2.85, d / 2 + 0.6)
773:     awning.rotation.x = -0.14
774:     awning.castShadow = true
775:     group.add(awning)
