.style-icon { color: var(--pink); background: rgba(255,63,142,.12); }
.service-intro h3 { margin: 0 0 4px; font-family: var(--font-display); font-size: 20px; letter-spacing: .03em; }
.service-intro p, .service-card p { margin: 0; color: rgba(255,255,255,.5); font-size: 10px; line-height: 1.5; }
.service-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
