  border-radius: 11px;
  background: rgba(15, 17, 27, .92);
}
.service-card > div { min-width: 0; }
.service-card b { display: block; margin-bottom: 4px; font-size: 11px; letter-spacing: .035em; }
.service-action {
  flex: 0 0 auto;
  min-width: 112px;
  padding: 9px 11px;
  border: 0;
  border-radius: 7px;
  background: linear-gradient(120deg, var(--gold), var(--coral));
  color: #24160c;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .08em;
  cursor: pointer;
  transition: filter .15s, transform .15s;
}
.service-action:hover:not(:disabled) { filter: brightness(1.12); transform: translateY(-1px); }
.service-action:active:not(:disabled) { transform: scale(.97); }
.service-action:disabled { background: rgba(255,255,255,.09); color: rgba(255,255,255,.35); cursor: default; }
.service-note { margin: 2px 3px 0; color: rgba(255,255,255,.38); font-size: 9px; line-height: 1.5; }
