  .service-head h2 { font-size: 28px; }
  .service-content { max-height: none; flex: 1; min-height: 0; padding-bottom: 12px; }
  .service-card { align-items: flex-start; padding: 11px; }
  .service-action { min-width: 94px; padding: 9px 8px; font-size: 7px; }
  .service-intro { padding: 12px; }
  .service-intro h3 { font-size: 18px; }
}

@media (max-width: 420px) {
  .service-panel { padding-right: 10px; padding-left: 10px; }
  .service-card { gap: 8px; }
  .service-card p { font-size: 9px; }
  .service-action { min-width: 82px; }
  .service-balance { padding: 10px; }
  .service-balance b { font-size: 16px; }
}

